TLM.f("Sancti/08-27",{"officium":"S. Josephi Calasanctii Confessoris","rule":["vide C5;","Gloria"],"fallback":"Commune/C5","from":{"GradualeP":"Commune/C5","Tractus":"Commune/C5"},"sections":{"Introitus":[{"k":"ref","la":"Ps 33:12"},{"k":"text","la":"Veníte, fílii, audíte me: timorem Dómini docébo vos."},{"k":"ref","la":"Ps 33:2"},{"k":"text","la":"Benedícam Dóminum in omni témpore: semper laus ejus in ore meo."},{"k":"macro","name":"Gloria"},{"k":"text","la":"Veníte, fílii, audíte me: timorem Dómini docébo vos."}],"Oratio":[{"k":"text","la":"Deus, qui per sanctum Joséphum Confessórem tuum, ad erudiéndam spíritu intellegéntiæ ac pietátis juventútem, novum Ecclésiæ tuæ subsídium providére dignátus es: præsta, quǽsumus; nos, ejus exémplo et intercessióne, ita fácere et docére, ut præmia consequámur ætérna."},{"k":"macro","name":"Per Dominum"}],"Lectio":[{"k":"text","la":"Léctio libri Sapiéntiæ"},{"k":"ref","la":"Sap 10:10-14"},{"k":"text","la":"Justum dedúxit Dóminus per vias rectas, et ostendit illi regnum Dei, et dedit illi sciéntiam sanctórum: honestávit illum in labóribus, et complévit labores illíus. In fraude circumveniéntium illum áffuit illi, et honéstum fecit illum. Custodívit illum ab inimícis, et a seductóribus tutávit illum, et certámen forte dedit illi, ut vínceret et sciret, quóniam ómnium poténtior est sapiéntia. Hæc vénditum justum non derelíquit, sed a peccatóribus liberávit eum: descendítque cum illo in fóveam, et in vínculis non derelíquit illum, donec afférret illi sceptrum regni, et poténtiam advérsus eos, qui eum deprimébant: et mendáces osténdit, qui maculavérunt illum, et dedit illi claritátem ætérnam, Dóminus, Deus noster."}],"Graduale":[{"k":"ref","la":"Ps 36:30-31"},{"k":"text","la":"Os justi meditábitur sapiéntiam, et lingua ejus loquétur judícium."},{"k":"text","la":"Lex Dei ejus in corde ipsíus: et non supplantabúntur gressus ejus.","mark":"V"},{"k":"text","la":"Allelúja, allelúja."},{"k":"ref","la":"Jac 1:12"},{"k":"text","la":"Beátus vir, qui suffert tentatiónem: quóniam, cum probátus fúerit, accípiet corónam vitæ. Allelúja."}],"GradualeP":[{"k":"text","la":"Allelúja, allelúja."},{"k":"ref","la":"Jas 1:12"},{"k":"text","la":"Beátus vir, qui suffert tentatiónem: quóniam, cum probátus fúerit, accípiet corónam vitæ. Allelúja."},{"k":"ref","la":"Eccli 45:9"},{"k":"text","la":"Amávit eum Dóminus et ornávit eum: stolam glóriæ índuit eum. Allelúja."}],"Tractus":[{"k":"ref","la":"Ps 91:13; 91:14"},{"k":"text","la":"Justus ut palma florébit: sicut cedrus Líbani multiplicábitur in domo Dómini."},{"k":"ref","la":"Ps 91:3"},{"k":"text","la":"Ad annuntiándum mane misericórdiam tuam, et veritátem tuam per noctem."},{"k":"sep"},{"k":"rubric","la":"Tractus"},{"k":"ref","la":"Ps 111:1-3"},{"k":"text","la":"Beátus vir, qui timet Dóminum: in mandátis ejus cupit nimis."},{"k":"text","la":"Potens in terra erit semen ejus: generátio rectórum benedicétur.","mark":"V"},{"k":"text","la":"Glória et divítiæ in domo ejus: et justítia ejus manet in sǽculum sǽculi.","mark":"V"}],"Evangelium":[{"k":"text","la":"Sequéntia ✠ sancti Evangélii secúndum Matthǽum"},{"k":"ref","la":"Matt 18:1-5"},{"k":"text","la":"In illo témpore: Accessérunt discípuli ad Jesum, dicéntes: Quis, putas, major est in regno cœlorum? Et ádvocans Jesus parvulum, státuit eum in médio eórum et dixit: Amen, dico vobis, nisi convérsi fuéritis et efficiámini sicut párvuli, non intrabitis in regnum cœlórum. Quicúmque ergo humiliáverit se sicut párvulus iste, hic est major in regno cœlorum. Et qui suscéperit unum párvulum talem in nómine meo, me súscipit."}],"Offertorium":[{"k":"ref","la":"Ps 9:17"},{"k":"text","la":"Desidérium páuperum exaudívit Dóminus: præparatiónem cordis eórum audívit auris tua."}],"Secreta":[{"k":"text","la":"Altáre tuum, Dómine, munéribus cumulamus oblatis: ut ejus nobis fiant supplicatione propitia, cujus nos donasti patrocínio adjuvári."},{"k":"macro","name":"Per Dominum"}],"Communio":[{"k":"ref","la":"Marc 10:14"},{"k":"text","la":"Sínite párvulos veníre ad me, et ne prohibuéritis eos: tálium est enim regnum Dei."}],"Postcommunio":[{"k":"text","la":"Sanctificáti, Dómine, salutári mystério: quǽsumus; ut, intercedénte sancto Josépho Confessóre tuo, ad majus semper proficiámus pietátis increméntum."},{"k":"macro","name":"Per Dominum"}]},"hr":{"73857185f1a0e6a0":{"t":"Ps 33, 12, Ps 33, 2\n(Ps 33, 12) Dođite, sinovi, čujte me, naučit ću vas strahu Gospodnjemu. (Ps 33, 2) Blagoslivljat ću Gospodina u svako doba, uvijek je hvala njegova na ustima mojim.\n<i>Slava Ocu, i Sinu, i Duhu Svetomu. Kako bijaše na početku, tako i sada i vazda i u vijeke vjekova. Amen</i>.\n(Ps 33, 12) Dođite, sinovi, čujte me, naučit ću vas strahu Gospodnjemu.","kn":"(Ps. 33, 12). D-ođilte, djeco, čujte me; učit ću vas strahu Gospodnjem! (Ps 33, 2). Blagosivat ću Gospodina u svako doba, uvijek je hvala njegova u ustima mojim. Slava Ocu . . . Dođite . . .","knRef":"Kniewald 1942, str. 692–693 (snimka 347) (OCR)"},"1f76234271b3793a":{"t":"<i>Pomolimo se</i>.\nBože, koji si se udostojao po svetom Josipu priznavaocu svome pribaviti svojoj Crkvi novu pomoć za poučavanje mladeži u duhu znanja i pobožnosti, daj molimo, da po njegovu primjeru i zagovoru tako radimo i učimo da postignemo vječnu nagradu.\n<i>Po Gospodinu našemu Isusu Kristu, Sinu tvome: Koji s tobom živi i kraljuje u jedinstvu Duha Svetoga, Bog: po sve vijeke vjekova</i>.","kn":"Bože, koji si se dostojao po svetom Josipu, priznavaOiCu svomu. Crkvi svojoj dati novu pomoć Za uzgoj mladeži u duhu pravde i pobožnosti, podaj, molimo, da i mi, njegovim primjerom, taka činimo i učimo, te doatignemo vječne nagrade, po G. n.","knRef":"Kniewald 1942, str. 692–693 (snimka 347) (OCR)"},"e83d5e42a8b3608d":{"t":"Mudr 10, 10-14\nČitanje knjige Mudrosti. Gospodin je pravim putem vodio pravednika, pokazao mu Božje kraljevstvo, udijelio mu znanje svetih, obogatio ga u naporima i oplodio mu rad. Očuvao ga od varalica i obogatio ga. Zaštitio ga od neprijatelja, čuvao od zasjeda, dao mu da pobjedi u teškoj borbi i spoznao je da je mudrost jača od svega. Ona nije napustila pravednika, kada je bio prodan, nego ga je oslobodila iz ruku grješnika. I sašla je s njim u jamu i nije ga ostavila u lancima, dok mu nije pribavila vladarsko žezlo i vlast nad tlačiteljima. One koji su ga crnili otkrila je kao lašce, a njemu je Bog naš Gospodin udijelio vječnu slavu.","kn":"Čitanje Knjige mudrosti (10, 10-14). Goispodin je pravednika vodio pravim putem i pokazao mu kraljevstvo Božje i udijelio mu znanje svetih i obogatio ga u naporima i oplodio -mu rad. I pomogao mu je protiv onih, koji su ga htjeli prevariti i obogatio ga je. Štitio ga je od neprijatelja i očuvao dd 1 zasjeda i dao mu da pobijedi u teškoj borbi i da i upozna, kako je mudrost jača od svega. Ova nije [ zapustila pravednika, kad je bio prodan, nego ga I je oslobodila iz ruku grješndka. I sašla je s njim u I jamu i nije ga zapustila u lancima, sve dok mu nije pribavila kraljevskoga žezla i vlasti nad tlačiteljima. One, koji su ga ocrnili, pokaza,la je lašctma, a njemu je udijelio vječnu slavu Gospodin Bog naš.","knRef":"Kniewald 1942, str. 792–793 (snimka 397) (OCR)"},"1b752aadc1868ee3":{"t":"Ps 36, 30-31\nPravednikova usta raspravljaju o mudrosti i njegov jezik govori o pravdi. Zakon mu je Božji u srcu, i noge mu neće posrnuti.\n\nJak 1, 12\n<i>Aleluja</i>, <i>aleluja</i>.\nBlago čovjeku koji nadvlada napast, jer kad bude prokušan, primit će krunu života. <i>Aleluja</i>.","kn":"(Ps. 36, 30-31). Pravednikova usta govore mudrost i njegov jezik kazuje pravdu. Zakon je Božji u njegovu srcu i njegove noge ne ce posrnuti.\n\nAleluja, aleiuja. (Jak. 1, 12) Blago čovjeku, koji pretrpi napast, jer će primiti vijenac slave, kad bude prokušan, aleluja.","knRef":"Kniewald 1942, str. 540–541 (snimka 271) (OCR)"},"cd98b15fff32d4ca":{"t":"Mt 18, 1-5\nSlijedi sveto Evanđelje po Mateju. U ono vrijeme, pristupe učenici k Isusu i upitaju ga: Što misliš, tko je najveći u nebeskom kraljevstvu? Isus nato pozva jedno malo dijete, postavi ga pred njih i reče: Zaista vam kažem: ako se ne obratite i ne postanete kao djeca, nećete ući u nebesko kraljevstvo. Dakle, tko se ponizi kao ovo dijete, taj je najveći u nebeskom kraljevstvu. I još vam kažem: tko radi mene primi jedno dijete kao što je ovo, mene prima.","kn":"t Slijedi sv. evanđelje po Mateju (18, 1-5). u ono vrijeme pristupiše učenici k Isusu govoreći: Tko je dakle najveći u kraljevstvu nebeskom? Tada pozva IsiK dijete, postavi ga među njih i reče: Zaista vam kažan: Ako se ne obratite i ne budete kao djeca, ne ćete ući u kraljevstvo nebesko. Koji se dakle ponizi kao ovo dijete, onaj je najveći u kraljevstvu nebeskom. I tko primi jedno takvo dijete U moje ime, mene prima.","knRef":"Kniewald 1942, str. 574–575 (snimka 288) (OCR)"},"7075b094008b1d10":{"t":"Ps 9, 17\nGospodin je uslišio želju siromaha, čuo je težnju njihova srca.","kn":"(Ps. 9, 38). Želju je siromah ispunio Gospodin i uslišao je vapaj srca njihova.","knRef":"Kniewald 1942, str. 692–693 (snimka 347) (OCR)"},"1dc84ed490b0ba41":{"t":"Na oltar tvoj, Gospodine, polažemo prikazane darove, da nam pribave tvoju milost po zagovoru onoga koga si nam darovao da nas pomaže svojom zaštitom.\n<i>Po Gospodinu našemu Isusu Kristu, Sinu tvome: Koji s tobom živi i kraljuje u jedinstvu Duha Svetoga, Bog: po sve vijeke vjekova</i>.","kn":"Prinosimo Ti, Gospodine, na žrtveniku Tvome prikazane darove moleći Te, da Ti budu mili molitvom onoga, kojega si nam darovao kao zaštitnika, po G. n.","knRef":"Kniewald 1942, str. 692–693 (snimka 347) (OCR)"},"404159d2e4df1ef4":{"t":"Uistinu je dostojno i pravedno, pravo i spasonosno, da vazda i svagdje zahvaljujemo tebi, Gospodine, sveti Oče, svemogući vječni Bože, po Kristu Gospodinu našemu. – Po njemu tvoje veličanstvo hvale anđeli, klanjaju se gospodstva i dršću vlasti. Nebesa i nebeske sile i blaženi serafini zajedničkim klicanjem slave. Daj, molimo, s njima i naše glase primi dok govorimo poniznim hvalospjevom:","kn":"Uistinu je dostojno i pravedno, pravo i spasonosno, da vazda i svagdje zahvaljujemo Tebi, Gospodine sveti. Oče svemogući, vječni Bože, po Kristu, Gospotdiniu našemu, po kome veličanstvo Tvoje hvale anđeli, klanjaju Ti se gospodstva, tresu se vlasti. Nebesa Te i nebeske moći i blaženi serafini, zadružnim klicanjem zajedno slave. Zapovijedi, molimo, da se i naši glasovi združe s njihovima, smjernim isippvijedanjem govoreći:","knRef":"Kniewald 1942, str. 18–19 (snimka 10) (OCR)"},"1e804d3c4eab6d4b":{"t":"Mk 10, 14\nPustite malene da dođu k meni i nemojte im priječiti, jer takvim pripada kraljevstvo nebesko.","kn":"(Mk. 10, 14). Pustite djecu, neka dolaze k meni, i ne branite im, jer je takovih kraljevstvo nebesko.","knRef":"Kniewald 1942, str. 692–693 (snimka 347) (OCR)"},"7aeee3f36cd91baf":{"t":"<i>Pomolimo se</i>.\nPosvećeni spasonosnom tajnom, molimo, Gospodine, da po zagovoru svetoga Josipa priznavaoca svoga uvijek sve bolje napredujemo u pobožnosti.\n<i>Po Gospodinu našemu Isusu Kristu, Sinu tvome: Koji s tobom živi i kraljuje u jedinstvu Duha Svetoga, Bog: po sve vijeke vjekova</i>.","kn":"Posvećeni, Gospodine, spasonosnim otajstvom, molimo, da zagovorom svetog Josipa, priznavaoca Tvoga, neprestano napredujemo u bogoljubnostl, po G. n.","knRef":"Kniewald 1942, str. 692–693 (snimka 347) (OCR)"}}});
